// Package postgres is the inventory module's PostgreSQL persistence driver.
//
// ── IT IS NO LONGER A SKELETON ────────────────────────────────────────────────
//
// Hand-written rather than generated by `sqlc`, which is HELD (SKILL.md §3.2/§3.4).
// When sqlc is unheld these statements move to db/queries/ and this file keeps the
// mapping code, exactly as internal/order/adapter/postgres did first. The property
// that matters is unchanged either way: the SQL sits close enough to
// db/migrations/0002_inventory.sql to be reviewed against it.
//
// ── THE ONE THING THIS DRIVER GETS RIGHT THAT A NAIVE ONE WOULD NOT ───────────
//
// The balance is updated by ADDING A DELTA IN SQL:
//
//	on_hand_milli = stock_balances.on_hand_milli + EXCLUDED.on_hand_milli
//
// and NOT by reading it in Go, subtracting, and writing the result back.
//
// The reason is concurrency, and this service is built for concurrency: several
// terminals at several branches drain simultaneously, and two of them can sell the
// same article in the same instant. A read-modify-write loses that race silently —
// both transactions read 5.000, both compute 4.750, both write 4.750, and 0.250 kg
// of beans vanishes from the ledger with nothing anywhere recording that it did.
//
// A test for that bug would be a test asserting the arithmetic still works, which
// it does — in the absence of the race. So the property is asserted under actual
// concurrency by TestStockStore_ConcurrentDeductionsOnOneItemBothLand in
// integration_test.go.
//
// ── WHY THE MOVEMENT IS APPENDED BEFORE THE BALANCE IS TOUCHED ─────────────────
//
// Two writes, one transaction, in that order, and the order is the correctness:
//
//  1. INSERT the movement, ON CONFLICT (id) DO NOTHING.
//  2. Only if it actually inserted, apply the delta to the balance.
//
// Step 2 is conditional on step 1 having inserted, and that is the whole
// idempotency mechanism. A terminal retrying the batch that carried an order line
// re-presents the same deduction; the movement's primary key is that line's id
// (see domain.NewSaleDeduction), so the INSERT is a no-op, RowsAffected is 0, and
// the balance is left alone.
//
// Getting this backwards — updating the balance unconditionally, or checking
// existence first — produces a double deduction on every retry. A retry is not an
// edge case: a terminal cannot distinguish a lost response from a crash, so it
// sends the same batch again as a matter of course.
//
// ── WHY EVERYTHING IS BIGINT AND EVERY READ RE-PARSES ──────────────────────────
//
// Quantities cross this boundary as `money.Quantity.Milli()` going in and are
// re-parsed by the money kernel coming out, so the decimal grammar has exactly one
// implementation in this service. A float never touches a quantity: `0.1 + 0.2` is
// 0.30000000000000004, and a shelf at -0.30000000000000004 would be refused by the
// schema's decimal(12,3) bound at COMMIT with a constraint name and no context.
package postgres

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	identity "wal-asri-pos/services/api-backend/internal/identity/domain"
	inventory "wal-asri-pos/services/api-backend/internal/inventory/domain"
	inventoryuc "wal-asri-pos/services/api-backend/internal/inventory/usecase"
	money "wal-asri-pos/services/api-backend/internal/money/domain"
)

// ─────────────────────────────────────────────────────────────────────────────
// The store
// ─────────────────────────────────────────────────────────────────────────────

// StockStore persists movements and derives balances from them.
type StockStore struct{ pool *pgxpool.Pool }

// NewStockStore wires the store.
func NewStockStore(pool *pgxpool.Pool) *StockStore { return &StockStore{pool: pool} }

var _ inventoryuc.StockStore = (*StockStore)(nil)

// TrackedItemFor resolves a sold variant to the article whose stock it consumes.
//
// BRANCH-SCOPED, and it has to be: two branches of one shop stock different things,
// and a lookup that ignored the branch would deduct a Bangkok branch's flour because
// a Chiang Mai terminal sold a latte.
//
// `track_stock` is part of the WHERE clause rather than something the caller
// filters on the result. Returning an untracked item and letting the usecase skip it
// would make "no article exists" and "article exists but is not counted" the same
// observation at this boundary, and only one of them is a decision.
func (s *StockStore) TrackedItemFor(
	ctx context.Context, branchID, productVariantID identity.UUIDv7,
) (inventory.InventoryItem, bool, error) {
	row := s.pool.QueryRow(ctx, `
		SELECT id, branch_id, product_variant_id, sku, name_th, name_en,
		       unit, track_stock, is_raw, version, created_at, updated_at
		  FROM inventory_items
		 WHERE branch_id = $1
		   AND product_variant_id = $2
		   AND track_stock`,
		branchID, productVariantID)

	item, err := scanItem(row)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			// FALSE, NOT AN ERROR. See the port's documentation: a variant with no
			// tracked article is a normal case — a new menu item whose stock-keeping
			// nobody has finished — and turning it into an error would fail the whole
			// ingest and leave the terminal retrying forever.
			return inventory.InventoryItem{}, false, nil
		}
		return inventory.InventoryItem{}, false, err
	}
	return item, true, nil
}

// ApplyDeductions appends every movement and updates every balance in ONE
// transaction, returning the balances as they now stand.
//
// AN EMPTY SLICE OPENS NO TRANSACTION. An order whose every line is untracked has
// nothing to deduct, and the distinction between "nothing to do" and "wrote
// something that changed nothing" is worth preserving — but the use case already
// short-circuits, so this is belt and braces for a direct caller.
//
// A failure anywhere rolls the whole thing back, so a partially-deducted order is
// not representable. The caller treats that as a failed ingest: the sale is real,
// so it must be retried, and thanks to the movement's borrowed id the retry is a
// no-op for anything that did land.
func (s *StockStore) ApplyDeductions(
	ctx context.Context, deductions []inventory.Deduction,
) ([]inventory.StockBalance, error) {
	if len(deductions) == 0 {
		return nil, nil
	}

	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("postgres: beginning the stock deduction: %w", err)
	}
	// Rollback after a successful Commit is a no-op, so this needs no success flag.
	defer func() { _ = tx.Rollback(context.WithoutCancel(ctx)) }()

	// The articles this sale CONSUMED, in first-seen order, so the caller gets one
	// balance per article even when an order rings the same item twice.
	//
	// Collected from EVERY deduction, including the ones whose movement already
	// existed — NOT only from the ones this call newly appended. That distinction is
	// load-bearing and getting it wrong silently drops the oversold warning on every
	// retry:
	//
	// A retry appends nothing, so a "what did I just change" list would be empty, so
	// no balance would come back, so no warning would be reported. The terminal that
	// lost the first response and retried would then receive an acknowledgement with
	// no stock_alerts while the shelf sits at -0.750 kg. The sale would warn on its
	// first attempt and silently not warn on its second — and the second response is
	// the one the cashier's terminal actually keeps, since it is the one that arrived.
	//
	// The balance of an article this sale consumed is well defined whether or not
	// this particular attempt was the one that moved it. That is what makes the
	// acknowledgement deterministic across retries, which matters because it is
	// stored and replayed verbatim for 24 hours.
	var (
		order   []identity.UUIDv7
		touched = make(map[identity.UUIDv7]bool, len(deductions))
	)

	for _, d := range deductions {
		m := d.Movement
		if err := m.Validate(); err != nil {
			return nil, err
		}

		if !touched[m.InventoryItemID] {
			touched[m.InventoryItemID] = true
			order = append(order, m.InventoryItemID)
			// Pessimistic lock the row BEFORE applying the delta to prevent race conditions.
			_, err := tx.Exec(ctx, `SELECT 1 FROM stock_balances WHERE inventory_item_id = $1 FOR UPDATE`, m.InventoryItemID)
			if err != nil {
				return nil, fmt.Errorf("postgres: locking balance for article %s: %w", m.InventoryItemID, err)
			}
		}

		inserted, err := appendMovement(ctx, tx, m)
		if err != nil {
			return nil, err
		}
		if !inserted {
			// Already in the ledger: this exact line was deducted before, so the
			// balance already includes it. Skipping the WRITE is the idempotency
			// guarantee, not a tolerated failure — and note the article is still in
			// `order` above, so its current balance is still reported.
			continue
		}
		if err := applyDelta(ctx, tx, m); err != nil {
			return nil, err
		}
	}

	// Read the balances back INSIDE the transaction, so what the caller is warned
	// about is what was stored rather than what a prior read suggested. This is
	// what removes the TOCTOU window documented at usecase.DeductSale.Execute.
	balances := make([]inventory.StockBalance, 0, len(order))
	for _, itemID := range order {
		balance, err := readBalance(ctx, tx, itemID)
		if err != nil {
			return nil, err
		}
		balances = append(balances, balance)
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("postgres: committing the stock deduction: %w", err)
	}
	return balances, nil
}

// ReverseForVoid executes an inverse database query, automatically crediting the raw ingredient milli-units
// back into the stock_balances ledger.
func (s *StockStore) ReverseForVoid(ctx context.Context, branchID identity.UUIDv7, orderID identity.UUIDv7) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(context.WithoutCancel(ctx)) }()

	// 1. Insert refund movements (negating the sale's quantity_milli).
	_, err = tx.Exec(ctx, `
		INSERT INTO stock_movements (id, inventory_item_id, branch_id, type, quantity_milli, reference_order_line_id, source, created_at)
		SELECT gen_random_uuid(), sm.inventory_item_id, sm.branch_id, 'refund', -sm.quantity_milli, sm.reference_order_line_id, 'sync_void_reversal', now()
		FROM order_lines ol
		JOIN stock_movements sm ON sm.reference_order_line_id = ol.id
		WHERE ol.order_id = $1
		  AND sm.type = 'sale'`, orderID)
	if err != nil {
		return fmt.Errorf("postgres: inserting refund movements: %w", err)
	}

	// 2. Pessimistic lock each affected balance row BEFORE updating.
	rows, err := tx.Query(ctx, `
		SELECT DISTINCT sm.inventory_item_id
		FROM stock_movements sm
		JOIN order_lines ol ON sm.reference_order_line_id = ol.id
		WHERE sm.type = 'sale' AND ol.order_id = $1`, orderID)
	if err != nil {
		return fmt.Errorf("postgres: selecting refund rows: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		var itemID identity.UUIDv7
		if err := rows.Scan(&itemID); err != nil {
			return fmt.Errorf("postgres: scanning item id: %w", err)
		}
		_, err := tx.Exec(ctx, `SELECT 1 FROM stock_balances WHERE inventory_item_id = $1 FOR UPDATE`, itemID)
		if err != nil {
			return fmt.Errorf("postgres: locking balance for article %s: %w", itemID, err)
		}
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("postgres: iterating refund rows: %w", err)
	}

	// 3. Update stock balances: add the credit.
	_, err = tx.Exec(ctx, `
		UPDATE stock_balances
		SET on_hand_milli = stock_balances.on_hand_milli - sm.quantity_milli,
		    updated_at = now()
		FROM stock_movements sm
		JOIN order_lines ol ON sm.reference_order_line_id = ol.id
		WHERE sm.type = 'sale' AND ol.order_id = $1
		  AND stock_balances.inventory_item_id = sm.inventory_item_id`, orderID)
	if err != nil {
		return fmt.Errorf("postgres: updating balances for refund: %w", err)
	}

	return tx.Commit(ctx)
}

// ReconcileBalances atomically realigns stock_balances with the stock_movements ledger.
//
// For each tracked item in the branch, it locks the balance row in
// inventory_item_id order, compares the ledger sum to the current balance,
// and if they differ, inserts a count_correction movement and updates the balance.
// All work happens in a single transaction with an audit row recording the
// corrections. Items are returned in the order they were locked (by item id).
func (s *StockStore) ReconcileBalances(ctx context.Context, branchID identity.UUIDv7) (inventory.ReconcileResult, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return inventory.ReconcileResult{}, err
	}
	defer func() { _ = tx.Rollback(context.WithoutCancel(ctx)) }()

	// Lock all balance rows in inventory_item_id order to prevent deadlocks.
	rows, err := tx.Query(ctx, `
		SELECT inventory_item_id, on_hand_milli
		FROM stock_balances
		WHERE branch_id = $1
		FOR UPDATE OF stock_balances`, branchID)
	if err != nil {
		return inventory.ReconcileResult{}, err
	}
	defer rows.Close()

	var items []inventory.ReconcileItem
	corrected := 0
	unchanged := 0
	for rows.Next() {
		var itemID identity.UUIDv7
		var currentMilli int64
		if err := rows.Scan(&itemID, &currentMilli); err != nil {
			return inventory.ReconcileResult{}, err
		}

		var ledgerSum int64
		err = tx.QueryRow(ctx, `
			SELECT COALESCE(SUM(quantity_milli), 0)
			FROM stock_movements
			WHERE inventory_item_id = $1`, itemID).Scan(&ledgerSum)
		if err != nil {
			return inventory.ReconcileResult{}, err
		}

		if ledgerSum != currentMilli {
			// Insert count_correction movement
			movementID := uuid.New()
			delta := ledgerSum - currentMilli
			movementType := "count_correction"
			_, err = tx.Exec(ctx, `
				INSERT INTO stock_movements (
					id, inventory_item_id, branch_id, type, quantity_milli,
					reference_order_line_id, source, created_at, created_by
				) VALUES ($1, $2, $3, $4, $5, NULL, 'sync_reconcile', $6, NULL)
				ON CONFLICT (id) DO NOTHING`,
				movementID, itemID, branchID, movementType, delta, time.Now().UTC(),
			)
			if err != nil {
				return inventory.ReconcileResult{}, fmt.Errorf("postgres: appending count_correction movement: %w", err)
			}

			// Update balance
			_, err = tx.Exec(ctx, `
				UPDATE stock_balances
				SET on_hand_milli = $1, updated_at = now(), version = version + 1
				WHERE inventory_item_id = $2`, ledgerSum, itemID)
			if err != nil {
				return inventory.ReconcileResult{}, err
			}

			items = append(items, inventory.ReconcileItem{
				InventoryItemID: itemID,
				BeforeMilli:    currentMilli,
				AfterMilli:     ledgerSum,
			})
			corrected++
		} else {
			items = append(items, inventory.ReconcileItem{
				InventoryItemID: itemID,
				BeforeMilli:    currentMilli,
				AfterMilli:     currentMilli,
			})
			unchanged++
		}
	}

	if err := rows.Err(); err != nil {
		return inventory.ReconcileResult{}, err
	}

	// Insert audit row with all corrections
	auditID := uuid.New()
	detail, err := json.Marshal(map[string]interface{}{
		"reason":          "stock_reconcile",
		"corrections":     items,
		"correctedCount":  corrected,
		"unchangedCount":  unchanged,
	})
	if err != nil {
		return inventory.ReconcileResult{}, fmt.Errorf("postgres: marshaling audit detail: %w", err)
	}

	_, err = tx.Exec(ctx, `
		INSERT INTO audit_log (id, actor_type, actor_id, branch_id, action, entity_type, entity_id, detail, created_at)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
		auditID, "operator", "", branchID, "stock_reconcile", "stock_branch_reconcile", branchID, detail, time.Now().UTC(),
	)
	if err != nil {
		return inventory.ReconcileResult{}, fmt.Errorf("postgres: inserting audit log: %w", err)
	}

	if err := tx.Commit(ctx); err != nil {
		return inventory.ReconcileResult{}, err
	}

	return inventory.ReconcileResult{
		BranchID:       branchID,
		CorrectedCount: corrected,
		Items:          items,
	}, nil
}

// appendMovement inserts one ledger row, reporting whether it was NEW.
//
// `ON CONFLICT (id) DO NOTHING` rather than a prior SELECT: the unique index is the
// only thing that closes the window between two concurrent retries of the same
// submission, and a read-then-write would let both through.
//
// RowsAffected is what distinguishes "appended" from "already there", and the
// caller MUST branch on it. Ignoring it is the double-deduction bug.
func appendMovement(ctx context.Context, tx pgx.Tx, m inventory.StockMovement) (bool, error) {
	tag, err := tx.Exec(ctx, `
		INSERT INTO stock_movements (
			id, inventory_item_id, branch_id, type, quantity_milli,
			reference_order_line_id, source, created_at, created_by
		) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
		ON CONFLICT (id) DO NOTHING`,
		m.ID, m.InventoryItemID, m.BranchID, string(m.Type),
		// THE ONLY PLACE A QUANTITY IS WRITTEN. int64 milli-units, never a float and
		// never a decimal string: the column is BIGINT and pgx sends an int64.
		m.QuantityMilli.Milli(),
		m.ReferenceOrderLineID, m.Source, m.CreatedAt, m.CreatedBy,
	)
	if err != nil {
		return false, fmt.Errorf("postgres: appending movement %s: %w", m.ID, err)
	}
	return tag.RowsAffected() == 1, nil
}

// applyDelta adds the movement's quantity to the article's balance.
//
// ── THE UPSERT, AND WHY IT IS AN UPSERT RATHER THAN AN UPDATE ─────────────────
//
// An article that has never been counted has NO balance row, and the first sale
// must create one. `ON CONFLICT (inventory_item_id) DO UPDATE` handles both cases
// in one statement, so there is no read-then-insert window where two concurrent
// first sales each create a row.
//
// The new row's on_hand IS the delta, not zero plus the delta written separately —
// the INSERT branch below puts it in the VALUES list. Starting a first sale's
// balance at zero and then adding to it would be two operations where one is
// correct, and the two-operation version is where an off-by-one-deduction lives.
//
// THE UPDATE IS `= stock_balances.on_hand_milli + EXCLUDED.on_hand_milli`, and the
// qualified column name is load-bearing: without `stock_balances.` the right-hand
// side would be ambiguous between the existing row and the proposed one. See the
// package note for why this is a += and not a read-modify-write.
//
// NO `>= 0` ON on_hand_milli, AND NOT BY ACCIDENT. See db/migrations/0002_inventory.sql
// and domain's package header: a negative balance is a committed fact an operator
// must be able to see. The policy is the ABSENCE of a constraint, so there is
// nothing here to add by accident — and nothing to "fix" later either.
func applyDelta(ctx context.Context, tx pgx.Tx, m inventory.StockMovement) error {
	_, err := tx.Exec(ctx, `
		INSERT INTO stock_balances (
			inventory_item_id, branch_id, on_hand_milli, reserved_milli,
			last_movement_id, version, created_at, updated_at
		) VALUES ($1, $2, $3, 0, $4, 1, $5, $5)
		ON CONFLICT (inventory_item_id) DO UPDATE
		   SET on_hand_milli    = stock_balances.on_hand_milli + EXCLUDED.on_hand_milli,
		       last_movement_id  = EXCLUDED.last_movement_id,
		       version           = stock_balances.version + 1,
		       updated_at        = EXCLUDED.updated_at`,
		m.InventoryItemID, m.BranchID, m.QuantityMilli.Milli(), m.ID, m.CreatedAt,
	)
	if err != nil {
		return fmt.Errorf("postgres: applying %d milli-units to article %s: %w",
			m.QuantityMilli.Milli(), m.InventoryItemID, err)
	}
	return nil
}

// readBalance reads one article's committed balance.
func readBalance(ctx context.Context, tx pgx.Tx, itemID identity.UUIDv7) (inventory.StockBalance, error) {
	row := tx.QueryRow(ctx, `
		SELECT id, inventory_item_id, branch_id, on_hand_milli, reserved_milli,
		       last_movement_id, version, created_at, updated_at
		  FROM stock_balances
		 WHERE inventory_item_id = $1`, itemID)
	return scanBalance(row)
}

// ─────────────────────────────────────────────────────────────────────────────
// Reads, for tests and for the read-only balances endpoint
// ─────────────────────────────────────────────────────────────────────────────

// Balance returns one article's current balance.
//
// Read-only, and deliberately so: the contract describes GET /inventory/balances
// as read-only — "There is deliberately no `PUT` or `PATCH`" — because `on_hand` is
// DERIVED from the ledger. A method that let a caller set it would be the second
// write surface that rule exists to prevent.
func (s *StockStore) Balance(ctx context.Context, itemID identity.UUIDv7) (inventory.StockBalance, error) {
	row := s.pool.QueryRow(ctx, `
		SELECT id, inventory_item_id, branch_id, on_hand_milli, reserved_milli,
		       last_movement_id, version, created_at, updated_at
		  FROM stock_balances
		 WHERE inventory_item_id = $1`, itemID)
	return scanBalance(row)
}

// LedgerSum returns the sum of an article's movements, in milli-units.
//
// The counterpart to Balance, and the reason the ledger is a ledger. A caller can
// check `LedgerSum(item) == Balance(item).OnHand.Milli()` and know the projection
// still agrees with the history behind it; a disagreement is the signature of a
// movement that was written without its balance, or the reverse.
//
// The integration suite asserts exactly that identity against a live database,
// because a projection that quietly stops agreeing with its history is the failure
// this whole design exists to make impossible.
func (s *StockStore) LedgerSum(ctx context.Context, itemID identity.UUIDv7) (int64, error) {
	var sum *int64
	err := s.pool.QueryRow(ctx,
		`SELECT sum(quantity_milli) FROM stock_movements WHERE inventory_item_id = $1`, itemID).Scan(&sum)
	if err != nil {
		return 0, fmt.Errorf("postgres: summing the ledger of article %s: %w", itemID, err)
	}
	if sum == nil {
		// An article with no movements has no sum, which is 0 rather than an
		// absence. `sql: Scan error` on a NULL would be a worse answer than a zero
		// the caller can compare against.
		return 0, nil
	}
	return *sum, nil
}

// MovementCount returns how many movements an article has.
func (s *StockStore) MovementCount(ctx context.Context, itemID identity.UUIDv7) (int, error) {
	var n int
	if err := s.pool.QueryRow(ctx,
		`SELECT count(*) FROM stock_movements WHERE inventory_item_id = $1`, itemID).Scan(&n); err != nil {
		return 0, fmt.Errorf("postgres: counting the movements of article %s: %w", itemID, err)
	}
	return n, nil
}

// ─────────────────────────────────────────────────────────────────────────────
// Paginated balances query
// ─────────────────────────────────────────────────────────────────────────────

// Balances returns a paginated list of stock balances for a branch.
//
// The query supports incremental pulls via `Since` (strictly greater than
// `updated_at`) and cursor-based pagination via `Cursor` (opaque token from
// `NextCursor`). When `ItemIDs` is non-empty, only those items are returned.
//
// The cursor is encoded as `updated_at|inventory_item_id` to provide a stable
// pagination position that survives concurrent inserts and updates.
func (s *StockStore) Balances(ctx context.Context, q inventory.BalancesQuery, pulledAt time.Time) (inventory.BalancesSnapshot, error) {
	// Build the WHERE clause dynamically
	where := "WHERE b.branch_id = $1"
	args := []any{q.BranchID}
	argPos := 2

	if q.Since != nil {
		where += fmt.Sprintf(" AND b.updated_at > $%d", argPos)
		args = append(args, *q.Since)
		argPos++
	}

	if len(q.ItemIDs) > 0 {
		// Build IN clause
		placeholders := make([]string, len(q.ItemIDs))
		for i, id := range q.ItemIDs {
			placeholders[i] = fmt.Sprintf("$%d", argPos+i)
			args = append(args, id)
		}
		where += fmt.Sprintf(" AND b.inventory_item_id IN (%s)", strings.Join(placeholders, ","))
		argPos += len(q.ItemIDs)
	}

	if q.Cursor != "" {
		// Cursor is "updated_at|inventory_item_id"
		parts := strings.Split(q.Cursor, "|")
		if len(parts) != 2 {
			return inventory.BalancesSnapshot{}, fmt.Errorf("postgres: invalid cursor format")
		}
		cursorTime, err := time.Parse(time.RFC3339Nano, parts[0])
		if err != nil {
			return inventory.BalancesSnapshot{}, fmt.Errorf("postgres: invalid cursor timestamp: %w", err)
		}
		cursorItemID, err := identity.ParseUUIDv7(parts[1])
		if err != nil {
			return inventory.BalancesSnapshot{}, fmt.Errorf("postgres: invalid cursor item id: %w", err)
		}
		// For cursor-based pagination: rows strictly after (updated_at, inventory_item_id)
		where += fmt.Sprintf(" AND (b.updated_at > $%d OR (b.updated_at = $%d AND b.inventory_item_id > $%d))", argPos, argPos, argPos+1)
		args = append(args, cursorTime, cursorItemID)
		argPos += 2
	}

	// Fetch one extra to detect if there's a next page
	limit := q.Limit + 1
	where += fmt.Sprintf(" ORDER BY b.updated_at, b.inventory_item_id LIMIT %d", limit)

	query := fmt.Sprintf(`
		SELECT b.id, b.inventory_item_id, b.branch_id, b.on_hand_milli, b.reserved_milli,
		       b.last_movement_id, b.version, b.created_at, b.updated_at
		FROM stock_balances b
		%s`, where)

	rows, err := s.pool.Query(ctx, query, args...)
	if err != nil {
		return inventory.BalancesSnapshot{}, fmt.Errorf("postgres: querying balances: %w", err)
	}
	defer rows.Close()

	balances := make([]inventory.StockBalance, 0, q.Limit)
	for rows.Next() {
		balance, err := scanBalance(rows)
		if err != nil {
			return inventory.BalancesSnapshot{}, err
		}
		balances = append(balances, balance)
	}
	if err := rows.Err(); err != nil {
		return inventory.BalancesSnapshot{}, fmt.Errorf("postgres: iterating balances: %w", err)
	}

	var nextCursor *string
	if len(balances) > int(q.Limit) {
		// There's a next page - encode cursor as "updated_at|inventory_item_id"
		last := balances[q.Limit-1]
		cursorStr := last.UpdatedAt.UTC().Format(time.RFC3339Nano) + "|" + last.InventoryItemID.String()
		nextCursor = &cursorStr
		balances = balances[:q.Limit]
	}

	return inventory.BalancesSnapshot{
		BranchID:   q.BranchID,
		Balances:   balances,
		Cursor:     inventory.NewSyncCursor(pulledAt),
		PulledAt:   pulledAt,
		NextCursor: nextCursor,
	}, nil
}

// ─────────────────────────────────────────────────────────────────────────────
// Scanning
// ─────────────────────────────────────────────────────────────────────────────

// rowScanner is satisfied by pgx.Row and pgx.Rows, so one scan function serves a
// single row and a row loop.
type rowScanner interface {
	Scan(dest ...any) error
}

// scanItem reads one inventory_items row.
//
// Quantities are not here — an article has none, which is why this row has no
// money or milli-unit column to get wrong.
func scanItem(row rowScanner) (inventory.InventoryItem, error) {
	var (
		item                 inventory.InventoryItem
		id, branchID         identity.UUIDv7
		productVariantID     *identity.UUIDv7
		sku, nameTH          *string
		nameEN               *string
		unit                 string
		trackStock, isRaw    bool
		version              int64
		createdAt, updatedAt time.Time
	)

	if err := row.Scan(
		&id, &branchID, &productVariantID, &sku, &nameTH, &nameEN,
		&unit, &trackStock, &isRaw, &version, &createdAt, &updatedAt,
	); err != nil {
		return inventory.InventoryItem{}, fmt.Errorf("postgres: scanning an inventory item row: %w", err)
	}

	item.ID = id
	item.BranchID = branchID
	item.ProductVariantID = productVariantID
	item.NameTH = derefOrEmpty(nameTH)
	item.NameEN = nameEN
	item.Unit = unit
	item.TrackStock = trackStock
	item.IsRaw = isRaw
	item.Version = inventory.Version(version)
	// UTC at the scan, once, rather than at each use site: a TIMESTAMPTZ denotes
	// different instants in different sessions' timezones, and the domain compares
	// instants. Same rule as internal/order/adapter/postgres/scan.go.
	item.CreatedAt = createdAt.UTC()
	item.UpdatedAt = updatedAt.UTC()
	if sku != nil {
		item.SKU = *sku
	}
	return item, nil
}

// scanBalance reads one stock_balances row.
//
// THE QUANTITIES ARE RE-PARSED BY THE MONEY KERNEL, not cast. Two reasons, and
// the second is the one that bites:
//
//   - it validates on the way OUT as well as in, so a value that somehow got past
//     the CHECKs fails here with a named error instead of propagating as a
//     plausible-looking amount
//   - `money.Quantity` is a distinct type precisely so a count of milli-units
//     cannot be passed where an amount of money is expected, and dropping it here
//     would undo the only enforcement that exists
func scanBalance(row rowScanner) (inventory.StockBalance, error) {
	var (
		balance                       inventory.StockBalance
		id, inventoryItemID, branchID identity.UUIDv7
		lastMovementID                *identity.UUIDv7
		onHandMilli, reservedMilli    int64
		version                       int64
		createdAt, updatedAt          time.Time
	)

	if err := row.Scan(
		&id, &inventoryItemID, &branchID, &onHandMilli, &reservedMilli,
		&lastMovementID, &version, &createdAt, &updatedAt,
	); err != nil {
		return inventory.StockBalance{}, fmt.Errorf("postgres: scanning a stock balance row: %w", err)
	}

	// NEWQuantityFromMilli, NOT MustQuantityFromMilli: this is a read path, and a
	// corrupt row must produce an error a caller can report rather than a panic
	// that takes the server down mid-shift.
	onHand, err := money.NewQuantityFromMilli(onHandMilli)
	if err != nil {
		return inventory.StockBalance{}, fmt.Errorf(
			"postgres: balance %s: on_hand_milli %d is not a decimal(12,3) quantity: %w", id, onHandMilli, err)
	}
	reserved, err := money.NewQuantityFromMilli(reservedMilli)
	if err != nil {
		return inventory.StockBalance{}, fmt.Errorf(
			"postgres: balance %s: reserved_milli %d is not a decimal(12,3) quantity: %w", id, reservedMilli, err)
	}

	balance.ID = id
	balance.InventoryItemID = inventoryItemID
	balance.BranchID = branchID
	balance.OnHand = onHand
	balance.Reserved = reserved
	balance.LastMovementID = lastMovementID
	balance.Version = inventory.Version(version)
	balance.CreatedAt = createdAt.UTC()
	balance.UpdatedAt = updatedAt.UTC()
	return balance, nil
}

func derefOrEmpty(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func (s *StockStore) Append(ctx context.Context, a inventory.AuditLog) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("postgres: beginning the audit append: %w", err)
	}
	defer func() { _ = tx.Rollback(context.WithoutCancel(ctx)) }()

	_, err = tx.Exec(ctx, `
		INSERT INTO audit_log (
			id, actor_type, actor_id, branch_id, action, entity_type, entity_id, detail, created_at
		) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
		ON CONFLICT (id) DO NOTHING`,
		a.ID, "terminal", a.ActorID, a.BranchID, inventory.AuditStockAdjust, "stock_balance", a.EntityID, a.Detail, a.CreatedAt,
	)
	if err != nil {
		return fmt.Errorf("postgres: inserting audit log: %w", err)
	}
	return tx.Commit(ctx)
}

// Get retrieves an audit record by its ID.
//
// Satisfies usecase.AuditStore.Get. It is a thin alias over GetAudit so the
// store satisfies both the usecase port and the HTTP handler's reconcileStore
// interface, which spells the lookup `GetAudit`. One implementation, two
// names — the spelling difference is a port concern, not a behaviour one.
func (s *StockStore) Get(ctx context.Context, id identity.UUIDv7) (inventory.AuditLog, error) {
	return s.GetAudit(ctx, id)
}

// GetAudit retrieves an audit record by its ID.
func (s *StockStore) GetAudit(ctx context.Context, id identity.UUIDv7) (inventory.AuditLog, error) {
	row := s.pool.QueryRow(ctx, `
		SELECT id, actor_type, actor_id, branch_id, action, entity_type, entity_id, detail, created_at
		FROM audit_log WHERE id = $1`, id)

	var audit inventory.AuditLog
	var detailJSON []byte
	err := row.Scan(
		&audit.ID, &audit.ActorType, &audit.ActorID, &audit.BranchID,
		&audit.Action, &audit.EntityType, &audit.EntityID, &detailJSON, &audit.CreatedAt,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return inventory.AuditLog{}, fmt.Errorf("postgres: audit not found: %w", err)
		}
		return inventory.AuditLog{}, fmt.Errorf("postgres: scanning audit log: %w", err)
	}

	if err := json.Unmarshal(detailJSON, &audit.Detail); err != nil {
		return inventory.AuditLog{}, fmt.Errorf("postgres: unmarshaling audit detail: %w", err)
	}

	return audit, nil
}

// AdjustStock consumes a terminal claim and creates a movement and an audit.
//
// ONE TRANSACTION, and the idempotency is the audit id:
//
//  1. SELECT ... FOR UPDATE the balance row (pessimistic lock against
//     concurrent adjustments on the same article).
//  2. Verify the balance still agrees with the ledger. If not, 409 with a
//     stable code — the ledger has drifted and the adjustment cannot be
//     applied safely.
//  3. Compute the delta = resolvedQuantityMilli - cloudBalance (the balance
//     the ledger says is true, NOT the terminal's oldQuantityMilli claim).
//  4. INSERT the audit row with ON CONFLICT (id) DO NOTHING. This is the
//     idempotency gate. The audit detail records the CORRECT delta and
//     balance_after (computed from the cloud balance, not the terminal's
//     oldQuantityMilli). If the audit id already exists, return the
//     ORIGINAL delta from the stored audit and the CURRENT balance as
//     balanceAfterMilli.
//  5. If delta is zero, the audit is recorded but no movement is written.
//  6. Otherwise, INSERT the movement (adjustment_in/out) and UPDATE the
//     balance.
//
// The movement's id is the audit id, so a retry of the same claim is a no-op
// at the movement level as well as the audit level.
func (s *StockStore) AdjustStock(ctx context.Context, req inventory.AdjustStockRequest) (inventory.AdjustStockResult, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return inventory.AdjustStockResult{}, fmt.Errorf("postgres: beginning the stock adjustment: %w", err)
	}
	defer func() { _ = tx.Rollback(context.WithoutCancel(ctx)) }()

	// Step 1: SELECT ... FOR UPDATE the balance row.
	var currentMilli int64
	err = tx.QueryRow(ctx, `
		SELECT on_hand_milli FROM stock_balances
		WHERE inventory_item_id = $1 FOR UPDATE`, req.InventoryItemID).Scan(&currentMilli)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return inventory.AdjustStockResult{}, fmt.Errorf("postgres: no balance for article %s", req.InventoryItemID)
		}
		return inventory.AdjustStockResult{}, fmt.Errorf("postgres: locking balance for article %s: %w", req.InventoryItemID, err)
	}

	// Step 2: Verify the balance still agrees with the ledger.
	var ledgerSum int64
	err = tx.QueryRow(ctx, `
		SELECT COALESCE(SUM(quantity_milli), 0)
		FROM stock_movements WHERE inventory_item_id = $1`, req.InventoryItemID).Scan(&ledgerSum)
	if err != nil {
		return inventory.AdjustStockResult{}, fmt.Errorf("postgres: summing the ledger of article %s: %w", req.InventoryItemID, err)
	}
	if ledgerSum != currentMilli {
		return inventory.AdjustStockResult{}, fmt.Errorf(
			"postgres: balance %d disagrees with ledger sum %d for article %s; the ledger has drifted and the adjustment cannot be applied safely",
			currentMilli, ledgerSum, req.InventoryItemID)
	}

	// Step 3: Compute the delta (resolved - cloud balance, NOT oldQuantityMilli).
	deltaMilli := req.ResolvedQuantityMilli - currentMilli
	balanceAfterMilli := currentMilli + deltaMilli

	// Step 4: INSERT the audit row with CORRECT detail. This is the idempotency gate.
	detailJSON := fmt.Sprintf(`{"reason":%q,"delta_milli":%d,"balance_after_milli":%d}`, req.Reason, deltaMilli, balanceAfterMilli)
	tag, err := tx.Exec(ctx, `
		INSERT INTO audit_log (
			id, actor_type, actor_id, branch_id, action, entity_type, entity_id, detail, created_at
		) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
		ON CONFLICT (id) DO NOTHING`,
		req.AuditLogID, "terminal", req.ActorTerminalID, req.BranchID,
		inventory.AuditStockAdjust, "stock_balance", req.InventoryItemID,
		detailJSON, time.Now().UTC(),
	)
	if err != nil {
		return inventory.AdjustStockResult{}, fmt.Errorf("postgres: inserting audit log: %w", err)
	}
	if tag.RowsAffected() == 0 {
		// Duplicate audit id — read the existing audit to get the original delta,
		// and return the CURRENT balance as balanceAfterMilli.
		audit, err := s.GetAuditInTx(ctx, tx, req.AuditLogID)
		origDelta := int64(0)
		if err == nil && audit.Detail.DeltaMilli != nil {
			origDelta = *audit.Detail.DeltaMilli
		}
		return inventory.AdjustStockResult{
			AuditLogID:        req.AuditLogID,
			Applied:           false,
			DeltaMilli:        origDelta,
			BalanceAfterMilli: currentMilli,
		}, nil
	}

	// Step 5: If delta is zero, the audit is recorded but no movement is written.
	if deltaMilli == 0 {
		if err := tx.Commit(ctx); err != nil {
			return inventory.AdjustStockResult{}, fmt.Errorf("postgres: committing the stock adjustment: %w", err)
		}
		return inventory.AdjustStockResult{
			AuditLogID:        req.AuditLogID,
			Applied:           true,
			DeltaMilli:        0,
			BalanceAfterMilli: currentMilli,
		}, nil
	}

	// Step 6: INSERT the movement and UPDATE the balance.
	movementType := "adjustment_in"
	if deltaMilli < 0 {
		movementType = "adjustment_out"
	}
	_, err = tx.Exec(ctx, `
		INSERT INTO stock_movements (
			id, inventory_item_id, branch_id, type, quantity_milli,
			reference_order_line_id, source, created_at, created_by
		) VALUES ($1, $2, $3, $4, $5, NULL, 'sync_terminal_claim', $6, NULL)
		ON CONFLICT (id) DO NOTHING`,
		req.AuditLogID, req.InventoryItemID, req.BranchID, movementType, deltaMilli, time.Now().UTC(),
	)
	if err != nil {
		return inventory.AdjustStockResult{}, fmt.Errorf("postgres: appending the adjustment movement: %w", err)
	}

	_, err = tx.Exec(ctx, `
		UPDATE stock_balances
		SET on_hand_milli = on_hand_milli + $1, updated_at = now(), version = version + 1
		WHERE inventory_item_id = $2`, deltaMilli, req.InventoryItemID)
	if err != nil {
		return inventory.AdjustStockResult{}, fmt.Errorf("postgres: updating the balance for the adjustment: %w", err)
	}

	if err := tx.Commit(ctx); err != nil {
		return inventory.AdjustStockResult{}, fmt.Errorf("postgres: committing the stock adjustment: %w", err)
	}

	return inventory.AdjustStockResult{
		AuditLogID:        req.AuditLogID,
		Applied:           true,
		DeltaMilli:        deltaMilli,
		BalanceAfterMilli: balanceAfterMilli,
	}, nil
}

// GetAuditInTx retrieves an audit record by its ID within an existing transaction.
func (s *StockStore) GetAuditInTx(ctx context.Context, tx pgx.Tx, id identity.UUIDv7) (inventory.AuditLog, error) {
	row := tx.QueryRow(ctx, `
		SELECT id, actor_type, actor_id, branch_id, action, entity_type, entity_id, detail, created_at
		FROM audit_log WHERE id = $1`, id)

	var audit inventory.AuditLog
	var detailJSON []byte
	err := row.Scan(
		&audit.ID, &audit.ActorType, &audit.ActorID, &audit.BranchID,
		&audit.Action, &audit.EntityType, &audit.EntityID, &detailJSON, &audit.CreatedAt,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return inventory.AuditLog{}, fmt.Errorf("postgres: audit not found: %w", err)
		}
		return inventory.AuditLog{}, fmt.Errorf("postgres: scanning audit log: %w", err)
	}

	if err := json.Unmarshal(detailJSON, &audit.Detail); err != nil {
		return inventory.AuditLog{}, fmt.Errorf("postgres: unmarshaling audit detail: %w", err)
	}

	return audit, nil
}